public static void main(String[] args) {
    test("the viewer sees 01:00 the next day", () -> {
        var meeting = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        eq(asSeenIn(meeting, ZoneId.of("+09:00")).getHour(), 1);
        eq(asSeenIn(meeting, ZoneId.of("+09:00")).getDayOfMonth(), 11);
    });
    test("the viewer's view is the same instant", () -> {
        var meeting = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        ok(asSeenIn(meeting, ZoneId.of("+09:00")).toInstant().equals(meeting.toInstant()), "same moment");
    });
    test("moving the meeting keeps 17:00", () -> {
        var meeting = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        eq(movedTo(meeting, ZoneId.of("+09:00")).getHour(), 17);
        eq(movedTo(meeting, ZoneId.of("+09:00")).getDayOfMonth(), 10);
    });
    test("moving the meeting shifts the moment by 8 hours", () -> {
        var meeting = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        eq(Duration.between(movedTo(meeting, ZoneId.of("+09:00")).toInstant(), meeting.toInstant()).toSeconds(), 28800);
    });
    test("the same zone changes nothing (boundary)", () -> {
        var meeting = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        ok(asSeenIn(meeting, ZoneId.of("+01:00")).equals(meeting));
        ok(movedTo(meeting, ZoneId.of("+01:00")).equals(meeting));
    });
    System.exit(report());
}
