public static void main(String[] args) {
    test("the later-looking wall clock happened first", () -> {
        var tokyo = ZonedDateTime.of(2024, 3, 10, 10, 0, 0, 0, ZoneId.of("+09:00"));
        var paris = ZonedDateTime.of(2024, 3, 10, 9, 0, 0, 0, ZoneId.of("+01:00"));
        eq(earliest(List.of(paris, tokyo)), tokyo);
    });
    test("the same moment across zones is isEqual", () -> {
        var a = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        var b = ZonedDateTime.of(2024, 3, 11, 1, 0, 0, 0, ZoneId.of("+09:00"));
        ok(sameMoment(a, b));
    });
    test("the same moment across zones is not equals", () -> {
        var a = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        var b = ZonedDateTime.of(2024, 3, 11, 1, 0, 0, 0, ZoneId.of("+09:00"));
        ok(!looksIdentical(a, b));
    });
    test("identical values agree both ways (boundary)", () -> {
        var a = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        var b = ZonedDateTime.of(2024, 3, 10, 17, 0, 0, 0, ZoneId.of("+01:00"));
        ok(sameMoment(a, b));
        ok(looksIdentical(a, b));
    });
    test("a single element is the earliest", () -> {
        var only = ZonedDateTime.of(2024, 3, 10, 9, 0, 0, 0, ZoneId.of("+01:00"));
        eq(earliest(List.of(only)), only);
    });
    System.exit(report());
}
